import React from 'react';

const FamilyList = ({ families }) => {
    return (
        <div>
            <h2>Families Participating in the Trip</h2>
            <ul>
                {families.map((family, index) => (
                    <li key={index}>
                        {family.name} - Members: {family.members}
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default FamilyList;
